import assert from 'node:assert/strict';
import { execFileSync } from 'node:child_process';
import { mkdtempSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import test from 'node:test';

import { checkCommitRange, validateCommitMessage } from '../../scripts/check-ai-attribution.mjs';

function git(cwd, ...args) {
  return execFileSync('git', args, { cwd, encoding: 'utf8' }).trim();
}

function createRepository() {
  const cwd = mkdtempSync(join(tmpdir(), 'ai-attribution-'));
  git(cwd, 'init', '--quiet');
  git(cwd, 'config', 'core.autocrlf', 'false');
  git(cwd, 'config', 'user.name', 'CI Test');
  git(cwd, 'config', 'user.email', 'ci-test@example.invalid');
  writeFileSync(join(cwd, 'fixture.txt'), 'base\n');
  git(cwd, 'add', 'fixture.txt');
  git(cwd, 'commit', '--quiet', '-m', 'chore: add base fixture');
  return cwd;
}

function commit(cwd, message, content) {
  writeFileSync(join(cwd, 'fixture.txt'), `${content}\n`);
  git(cwd, 'add', 'fixture.txt');
  git(cwd, 'commit', '--quiet', '-m', message);
  return git(cwd, 'rev-parse', 'HEAD');
}

test('accepts a valid single-model declaration', () => {
  assert.deepEqual(
    validateCommitMessage('feat: example\n\nAssisted-by: Codex[GPT-5.6 Sol]\n', 'abc123'),
    [],
  );
});

test('accepts multiple complete tool and model pairs', () => {
  assert.deepEqual(
    validateCommitMessage(
      'feat: example\n\nAssisted-by: Codex[GPT-5], ChatGPT-Web[GPT-5.6 Thinking]\nAssisted-by: Claude-Code[Claude Opus 5]\n',
      'abc123',
    ),
    [],
  );
});

test('allows a commit with no AI assistance declaration', () => {
  assert.deepEqual(validateCommitMessage('fix: ordinary change\n', 'abc123'), []);
});

test('does not treat incidental AI-related wording as a declaration', () => {
  assert.deepEqual(
    validateCommitMessage(
      'fix(ci): remove the language-model secret check from rollback\n',
      'abc123',
    ),
    [],
  );
});

test('rejects malformed, incomplete, split and prose declarations with the SHA', () => {
  const cases = [
    'Assisted-by: Codex GPT-5.6 Sol',
    'Assisted-by: [GPT-5.6 Sol]',
    'Assisted-by: Codex[GPT-]',
    'Assisted-by: Codex[GPT-5.6 So]',
    'Assisted-by: Codex[YOUR-ACTUAL-CODEX-MODEL]',
    'Assisted-by: Codex[GPT-5.6 So\nl]',
    'Assisted by Claude Sonnet 5',
    'assisted-by: Codex[GPT-5.6 Sol]',
    'Co-Authored-By: Claude Opus 5 <noreply@anthropic.com>',
  ];

  for (const message of cases) {
    const errors = validateCommitMessage(`feat: example\n\n${message}\n`, 'deadbeef');
    assert.ok(errors.length > 0, message);
    assert.ok(
      errors.every((error) => error.includes('deadbeef')),
      message,
    );
  }
});

test('checks only commits introduced after the supplied base', () => {
  const cwd = createRepository();
  const historical = commit(cwd, 'fix: historical\n\nAssisted by Claude Sonnet 5', 'old');
  const base = commit(cwd, 'chore: establish pull request base', 'base');
  const valid = commit(cwd, 'feat: valid\n\nAssisted-by: Codex[GPT-5.6 Sol]', 'valid');
  const result = checkCommitRange({ base, head: valid, cwd });

  assert.deepEqual(result.commits, [valid]);
  assert.equal(result.commits.includes(historical), false);
  assert.deepEqual(result.errors, []);
});

test('reports the offending commit from a multi-commit range', () => {
  const cwd = createRepository();
  const base = git(cwd, 'rev-parse', 'HEAD');
  commit(cwd, 'feat: ordinary commit', 'ordinary');
  const malformed = commit(cwd, 'feat: malformed\n\nAssisted by Claude Sonnet 5', 'bad');
  const head = commit(cwd, 'feat: valid\n\nAssisted-by: Codex[GPT-5]', 'valid');
  const result = checkCommitRange({ base, head, cwd });

  assert.equal(result.commits.length, 3);
  assert.equal(result.errors.length, 1);
  assert.match(result.errors[0], new RegExp(malformed));
});

test('fails clearly for invalid revisions and Git execution failures', () => {
  const cwd = createRepository();

  assert.throws(
    () => checkCommitRange({ base: 'missing-base', cwd }),
    /invalid Git commit reference "missing-base"/,
  );
  assert.throws(
    () => checkCommitRange({ base: 'HEAD', cwd, gitBinary: 'missing-git-executable' }),
    /could not run Git/,
  );
});

test('Gitea Pull Request CI validates the actual base and head commit range', async () => {
  const { readFile } = await import('node:fs/promises');
  const workflow = await readFile(
    new URL('../../.gitea/workflows/ci.yml', import.meta.url),
    'utf8',
  );

  assert.match(workflow, /- name: Validate Pull Request AI attribution/);
  assert.match(workflow, /if: github\.event_name == 'pull_request'/);
  assert.match(workflow, /AI_ATTRIBUTION_BASE: \$\{\{ github\.event\.pull_request\.base\.sha \}\}/);
  assert.match(workflow, /AI_ATTRIBUTION_HEAD: \$\{\{ github\.event\.pull_request\.head\.sha \}\}/);
  assert.match(
    workflow,
    /npm run check:ai-attribution -- "\$AI_ATTRIBUTION_BASE" "\$AI_ATTRIBUTION_HEAD"/,
  );
});

#!/usr/bin/env node

import { spawnSync } from 'node:child_process';
import { pathToFileURL } from 'node:url';

const VALID_PAIR = String.raw`[^\[\],\r\n]*[A-Za-z][^\[\],\r\n]*\[[^\[\]\r\n]*[A-Za-z][^\[\]\r\n]*\d[^\[\]\r\n]*\]`;
const VALID_DECLARATION = new RegExp(`^Assisted-by: ${VALID_PAIR}(?:, ${VALID_PAIR})*$`);
const PLACEHOLDER_MODEL =
  /\b(?:actual|your[- ]actual|unknown|placeholder|todo|tbd)[- ]*(?:codex[- ])?model\b/i;
const TRUNCATED_MODEL_SUFFIX = /\d\s+[A-Za-z]{1,2}$/;
const OBVIOUS_PROSE_ATTEMPT = /\bassisted\s+by\b/i;
const AI_COAUTHOR = /^Co-Authored-By:.*(?:anthropic|openai|chatgpt|claude|codex)/i;

function runGit(args, { cwd = process.cwd(), gitBinary = 'git' } = {}) {
  const result = spawnSync(gitBinary, args, {
    cwd,
    encoding: 'utf8',
    maxBuffer: 16 * 1024 * 1024,
    shell: false,
    windowsHide: true,
  });

  if (result.error) {
    throw new Error(`could not run Git (${gitBinary}): ${result.error.message}`);
  }

  if (result.status !== 0) {
    const detail = (result.stderr || result.stdout || 'unknown Git error').trim();
    throw new Error(`Git ${args[0]} failed: ${detail}`);
  }

  return result.stdout;
}

function resolveCommit(ref, options) {
  try {
    return runGit(['rev-parse', '--verify', '--end-of-options', `${ref}^{commit}`], options).trim();
  } catch (error) {
    throw new Error(`invalid Git commit reference "${ref}": ${error.message}`);
  }
}

export function validateCommitMessage(message, sha = 'unknown') {
  const errors = [];
  const lines = message.replaceAll('\r\n', '\n').split('\n');

  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index];
    const lineNumber = index + 1;
    const trimmed = line.trim();

    if (trimmed.startsWith('Assisted-by:')) {
      if (line !== trimmed) {
        errors.push(
          `commit ${sha}, line ${lineNumber}: Assisted-by declarations must start at the beginning of the line`,
        );
        continue;
      }

      if (!VALID_DECLARATION.test(line)) {
        errors.push(
          `commit ${sha}, line ${lineNumber}: malformed Assisted-by declaration; use "Assisted-by: <tool>[<model>]" and separate multiple pairs with ", "`,
        );
        continue;
      }

      if (PLACEHOLDER_MODEL.test(line)) {
        errors.push(
          `commit ${sha}, line ${lineNumber}: replace the placeholder with the complete model actually used`,
        );
        continue;
      }

      const models = [...line.matchAll(/\[([^\[\]\r\n]+)\]/g)].map((match) => match[1]);
      const incompleteModel = models.find(
        (model) =>
          !/^[A-Za-z0-9].*[A-Za-z0-9]$/.test(model) ||
          !/[A-Za-z]/.test(model) ||
          !/\d/.test(model) ||
          TRUNCATED_MODEL_SUFFIX.test(model),
      );
      if (incompleteModel) {
        errors.push(
          `commit ${sha}, line ${lineNumber}: model "${incompleteModel}" appears incomplete; record the complete model name actually used`,
        );
      }

      continue;
    }

    if (/^assisted-by\s*:/i.test(trimmed)) {
      errors.push(
        `commit ${sha}, line ${lineNumber}: malformed Assisted-by label; use the exact case and hyphenation "Assisted-by:"`,
      );
      continue;
    }

    if (OBVIOUS_PROSE_ATTEMPT.test(line)) {
      errors.push(
        `commit ${sha}, line ${lineNumber}: prose AI attribution is not valid; use "Assisted-by: <tool>[<model>]"`,
      );
      continue;
    }

    if (AI_COAUTHOR.test(line)) {
      errors.push(
        `commit ${sha}, line ${lineNumber}: AI co-author metadata does not replace the required "Assisted-by: <tool>[<model>]" declaration`,
      );
    }
  }

  return errors;
}

export function checkCommitRange({
  base,
  head = 'HEAD',
  cwd = process.cwd(),
  gitBinary = 'git',
} = {}) {
  if (!base) {
    throw new Error('a base Git reference is required');
  }

  const options = { cwd, gitBinary };
  const baseSha = resolveCommit(base, options);
  const headSha = resolveCommit(head, options);

  let revisionList;
  try {
    revisionList = runGit(
      ['rev-list', '--reverse', '--topo-order', `${baseSha}..${headSha}`],
      options,
    );
  } catch (error) {
    throw new Error(`could not inspect commit range ${base}..${head}: ${error.message}`);
  }

  const commits = revisionList.split(/\r?\n/u).filter(Boolean);
  const errors = [];

  for (const sha of commits) {
    let message;
    try {
      message = runGit(['show', '--no-patch', '--format=%B', sha], options);
    } catch (error) {
      throw new Error(`could not read commit ${sha}: ${error.message}`);
    }
    errors.push(...validateCommitMessage(message, sha));
  }

  return { commits, errors };
}

function usage() {
  return 'Usage: node scripts/check-ai-attribution.mjs <base-ref> [head-ref]';
}

export function main(argv = process.argv.slice(2)) {
  if (argv.length < 1 || argv.length > 2 || argv.includes('--help') || argv.includes('-h')) {
    const stream = argv.includes('--help') || argv.includes('-h') ? process.stdout : process.stderr;
    stream.write(`${usage()}\n`);
    return argv.includes('--help') || argv.includes('-h') ? 0 : 2;
  }

  const [base, head = 'HEAD'] = argv;

  try {
    const result = checkCommitRange({ base, head });
    if (result.errors.length > 0) {
      process.stderr.write(`AI attribution validation failed for ${base}..${head}:\n`);
      process.stderr.write(`${result.errors.map((error) => `- ${error}`).join('\n')}\n`);
      return 1;
    }

    process.stdout.write(
      `AI attribution validation passed for ${result.commits.length} commit(s) in ${base}..${head}.\n`,
    );
    return 0;
  } catch (error) {
    process.stderr.write(`AI attribution validation could not run: ${error.message}\n`);
    return 2;
  }
}

if (process.argv[1] && import.meta.url === pathToFileURL(process.argv[1]).href) {
  process.exitCode = main();
}

